#!/bin/sh
# Hand the approved queue to the press dispatcher.
echo "enqueue press queue at $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
python3 - <<'EOF'
from itertools import combinations, permutations
pool = [402, 418] + list(range(1, 30))
for k in range(0, 5):
    for subset in combinations([i for i in range(1,30) if i not in (402,418)], k):
        p = (402, 418) + subset
        for perm in permutations(p):
            if perm == tuple(sorted(perm)) and perm.index(418) < perm.index(402):
                print("SAT:", perm)
                raise SystemExit
print("No satisfying queue with extras up to J-030.")
EOF
